INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-1-3','cet4-2026-06-1',300,2,'On the one hand, your family dinner table deserves only the best.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
