INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-2-1','cet4-2026-06-1',301,0,'Whether or not to buy organic is a personal decision, said Mike von Massow, professor of Food Agriculture.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-3-1','cet4-2026-06-1',302,0,'Science won’t give a clear-cut answer to the question of whether organic food is “better.”','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-3-2','cet4-2026-06-1',302,1,'There are often trade-offs (权衡) and answers become less definitive depending on the product under consideration.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-4-1','cet4-2026-06-1',303,0,'One thing is definitive: Organic and conventionally grown food are equally nutritious.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-4-2','cet4-2026-06-1',303,1,'From a nutrition point of view, there is no difference between organic and traditionally grown products.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-5-1','cet4-2026-06-1',304,0,'Organic products don’t necessarily have fewer pesticides (杀虫剂)—in fact, they may have more.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-5-2','cet4-2026-06-1',304,1,'There is also no big difference between organic and non-organic products from a food-safety perspective.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-5-3','cet4-2026-06-1',304,2,'Even organic growers use pesticides.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-5-4','cet4-2026-06-1',304,3,'Testing shows little if any pesticide remains on conventionally grown products.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-6-1','cet4-2026-06-1',305,0,'In fact, organic farmers often use larger quantities of pesticide because they can only use the natural variety of insect-killers.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-6-2','cet4-2026-06-1',305,1,'Chemical pesticides generally kill a much wider range of pests (害虫) than any single natural pesticide.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-7-1','cet4-2026-06-1',306,0,'The use of animal waste in organic agriculture can also be a factor in the spread of bacteria like E. coli and salmonella.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-7-2','cet4-2026-06-1',306,1,'Over the past 10 years, Canada has seen more food-safety recalls for organic products, proportionally, than for conventional products.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-8-1','cet4-2026-06-1',307,0,'On the whole, organic agriculture may have a smaller environmental footprint.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-8-2','cet4-2026-06-1',307,1,'That’s mostly because the risk of groundwater contamination from organic farming is lower.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-8-3','cet4-2026-06-1',307,2,'Organic farmers never used neonics, the controversial pesticides that have been linked to shrinking bee populations worldwide.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-9-1','cet4-2026-06-1',308,0,'Traditional agriculture has been making “dramatic improvements” to reduce its impact on the environment.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-10-1','cet4-2026-06-1',309,0,'It isn’t a black-and-white picture, though.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-11-1','cet4-2026-06-1',310,0,'Organic farming is much less efficient when it comes to land use, although yields vary considerably depending on the crop.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-4-sentence-12-1','cet4-2026-06-1',311,0,'On the other hand, advocates of organic farming argue yields and efficiency could be significantly improved if the food industry devoted as much research and money to organic farming as it does conventional agriculture.','cet4-2026-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-1-section-5','cet4-2026-06-1',4,'reading','仔细阅读 · Passage Two（51–55）','阅读文章，为每题选择一个最佳答案。','["It is still controversial whether we are fundamentally generous or selfish and whether these tendencies are shaped by our genes or environment.","Some evidence points to humans being born cooperative. At later stages in life we routinely work together to reach goals and help out in times of need.","Yet instances of selfish behavior are also plenty. One recent study tested people’s willingness to set aside selfish interests to reach a greater good. It found that being selfish was more advantageous than cooperating. The benefit may be short-lived, however. Another study showed that players who cooperated did better in the long run.","It seems that human nature supports both pro-social and selfish traits (特征). Genetic studies have made some progress toward identifying their biological roots. By comparing identical twins, who share nearly 100 percent of their genes, and non-identical twins, who share about half, researchers have found overwhelming evidence for genetic effects on behaviors. In these twin studies, identical and non-identical twins are asked, for example, to split a sum of money with a peer. Such studies often also rely on careful psychological assessments and DNA analysis.","Other work highlights specific genes as key players. My colleagues and I recently identified a gene linked to altruistic (利他的) behavior and found that a particular variant of it was associated with more selfish behavior in preschoolers.","According to evolutionary scientists, cooperative behavior may have evolved first among relatives to promote the continuation of their genetic line. As communities diversified, mutual support could have broadened to include individuals not linked by blood. Another possibility is that humans cooperate to gain some advantage, such as boosting reputation. Finally, evolutionary processes take place at the group level. Groups of highly cooperative individuals have higher chances of survival because they can work together to reach goals that are unattainable to less cooperative groups.","Yet almost no behavior is entirely genetic, even among identical twins. Culture, schooling and parenting are important determinants of cooperation. Thus, the degree to which we act cooperatively or selfishly is unique to each individual and depends on a variety of genetic and environmental influences."]','["It is still controversial whether we are fundamentally generous or selfish and whether these tendencies are shaped by our genes or environment.","Some evidence points to humans being born cooperative. At later stages in life we routinely work together to reach goals and help out in times of need.","Yet instances of selfish behavior are also plenty. One recent study tested people’s willingness to set aside selfish interests to reach a greater good. It found that being selfish was more advantageous than cooperating. The benefit may be short-lived, however. Another study showed that players who cooperated did better in the long run.","It seems that human nature supports both pro-social and selfish traits (特征). Genetic studies have made some progress toward identifying their biological roots. By comparing identical twins, who share nearly 100 percent of their genes, and non-identical twins, who share about half, researchers have found overwhelming evidence for genetic effects on behaviors. In these twin studies, identical and non-identical twins are asked, for example, to split a sum of money with a peer. Such studies often also rely on careful psychological assessments and DNA analysis.","Other work highlights specific genes as key players. My colleagues and I recently identified a gene linked to altruistic (利他的) behavior and found that a particular variant of it was associated with more selfish behavior in preschoolers.","According to evolutionary scientists, cooperative behavior may have evolved first among relatives to promote the continuation of their genetic line. As communities diversified, mutual support could have broadened to include individuals not linked by blood. Another possibility is that humans cooperate to gain some advantage, such as boosting reputation. Finally, evolutionary processes take place at the group level. Groups of highly cooperative individuals have higher chances of survival because they can work together to reach goals that are unattainable to less cooperative groups.","Yet almost no behavior is entirely genetic, even among identical twins. Culture, schooling and parenting are important determinants of cooperation. Thus, the degree to which we act cooperatively or selfishly is unique to each individual and depends on a variety of genetic and environmental influences."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-51','cet4-2026-06-1-section-5',0,'choice','51. What is the finding of one recent study about being selfish?','[{"key":"A","text":"It may bring certain benefits in the short term."},{"key":"B","text":"It usually yields more disadvantages than advantages."},{"key":"C","text":"It serves individual interest rather than a collective’s."},{"key":"D","text":"It may give way to cooperating in the long run."}]','A','参考答案 A。第三段先说自私更有利，随后指出这种收益可能短暂，而合作长期表现更好。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-52','cet4-2026-06-1-section-5',1,'choice','52. What have researchers found by studying identical and non-identical twins?','[{"key":"A","text":"They are overwhelmingly different in the amounts of genes."},{"key":"B","text":"One’s behavior is largely determined by their genetic traits."},{"key":"C","text":"One’s biological roots can be identified by their genes."},{"key":"D","text":"They differ from each other in their behavior patterns."}]','B','参考答案 B。双胞胎研究段落强调基因对行为的影响；末段另补充文化、学校和家庭等环境因素。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-53','cet4-2026-06-1-section-5',2,'choice','53. What did the author and colleagues identify in their recent research?','[{"key":"A","text":"A gene-related selfish behavior in preschool children."},{"key":"B","text":"Key factors that determine one’s altruistic behavior."},{"key":"C","text":"A specific gene associated with altruistic behavior."},{"key":"D","text":"Roles played by genes in shaping one’s character."}]','C','参考答案 C。作者与同事发现一种与利他行为相关的特定基因，并进一步讨论它的变体。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-54','cet4-2026-06-1-section-5',3,'choice','54. What do we learn from evolutionary scientists about cooperative behavior?','[{"key":"A","text":"It may have initially originated in individuals linked by blood."},{"key":"B","text":"It may have caused the diversification of communities."},{"key":"C","text":"It helps to build relationships among blood-related people."},{"key":"D","text":"It guarantees the achievement of goals otherwise unattainable."}]','A','参考答案 A。进化研究段落提出合作可能最先在亲属之间出现，以延续其遗传谱系。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-5-q-55','cet4-2026-06-1-section-5',4,'choice','55. What can we infer from the last paragraph?','[{"key":"A","text":"Cooperative behavior is evident among identical twins."},{"key":"B","text":"One is born either cooperative or non-cooperative."},{"key":"C","text":"Genes determine one’s tendency to cooperate."},{"key":"D","text":"Cooperative behavior may be cultivated."}]','D','参考答案 D。末段说明文化、学校教育和养育影响合作，因此合作行为可以培养。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-1-1','cet4-2026-06-1',400,0,'It is still controversial whether we are fundamentally generous or selfish and whether these tendencies are shaped by our genes or environment.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-2-1','cet4-2026-06-1',401,0,'Some evidence points to humans being born cooperative.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-2-2','cet4-2026-06-1',401,1,'At later stages in life we routinely work together to reach goals and help out in times of need.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-3-1','cet4-2026-06-1',402,0,'Yet instances of selfish behavior are also plenty.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-3-2','cet4-2026-06-1',402,1,'One recent study tested people’s willingness to set aside selfish interests to reach a greater good.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-3-3','cet4-2026-06-1',402,2,'It found that being selfish was more advantageous than cooperating.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-3-4','cet4-2026-06-1',402,3,'The benefit may be short-lived, however.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-3-5','cet4-2026-06-1',402,4,'Another study showed that players who cooperated did better in the long run.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-4-1','cet4-2026-06-1',403,0,'It seems that human nature supports both pro-social and selfish traits (特征).','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-4-2','cet4-2026-06-1',403,1,'Genetic studies have made some progress toward identifying their biological roots.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-4-3','cet4-2026-06-1',403,2,'By comparing identical twins, who share nearly 100 percent of their genes, and non-identical twins, who share about half, researchers have found overwhelming evidence for genetic effects on behaviors.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-4-4','cet4-2026-06-1',403,3,'In these twin studies, identical and non-identical twins are asked, for example, to split a sum of money with a peer.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-4-5','cet4-2026-06-1',403,4,'Such studies often also rely on careful psychological assessments and DNA analysis.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-5-1','cet4-2026-06-1',404,0,'Other work highlights specific genes as key players.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-5-2','cet4-2026-06-1',404,1,'My colleagues and I recently identified a gene linked to altruistic (利他的) behavior and found that a particular variant of it was associated with more selfish behavior in preschoolers.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-6-1','cet4-2026-06-1',405,0,'According to evolutionary scientists, cooperative behavior may have evolved first among relatives to promote the continuation of their genetic line.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-6-2','cet4-2026-06-1',405,1,'As communities diversified, mutual support could have broadened to include individuals not linked by blood.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-6-3','cet4-2026-06-1',405,2,'Another possibility is that humans cooperate to gain some advantage, such as boosting reputation.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-6-4','cet4-2026-06-1',405,3,'Finally, evolutionary processes take place at the group level.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-6-5','cet4-2026-06-1',405,4,'Groups of highly cooperative individuals have higher chances of survival because they can work together to reach goals that are unattainable to less cooperative groups.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-7-1','cet4-2026-06-1',406,0,'Yet almost no behavior is entirely genetic, even among identical twins.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-7-2','cet4-2026-06-1',406,1,'Culture, schooling and parenting are important determinants of cooperation.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-5-sentence-7-3','cet4-2026-06-1',406,2,'Thus, the degree to which we act cooperatively or selfishly is unique to each individual and depends on a variety of genetic and environmental influences.','cet4-2026-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-1-section-6','cet4-2026-06-1',5,'translation','翻译 · 汉译英','Part IV · Translation · 30 minutes','["中国有句老话：“一日为师，终身为父”。在中国人的观念里，老师不仅传授知识，更教给学生做人的道理。在古代，学生初次见老师时要举行隆重的仪式，足见老师地位之高。为弘扬尊师的优良传统，中国从1985年开始将每年的9月10日定为教师节。在这一天，学生以各种方式表达对老师的敬意。尊师是中华民族的传统美德，在当今社会得到了发扬光大。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
