INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-2-q-32','cet4-2026-06-2-section-2',6,'choice','32. 第 32 空','[{"key":"A","text":"addition"},{"key":"B","text":"approximately"},{"key":"C","text":"avoid"},{"key":"D","text":"consumption"},{"key":"E","text":"converted"},{"key":"F","text":"convince"},{"key":"G","text":"heightened"},{"key":"H","text":"omission"},{"key":"I","text":"opposite"},{"key":"J","text":"perceive"},{"key":"K","text":"prospect"},{"key":"L","text":"reinforcement"},{"key":"M","text":"separately"},{"key":"N","text":"simply"},{"key":"O","text":"targeted"}]','J','参考答案 J。perceive the bitterness 表示感知苦味。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
